def connectTwoGroups(cost: list[list[int]]) -> int:
    sz1 = len(cost)
    sz2 = len(cost[0])
    min_group2 = [min(cost[i][j] for i in range(sz1)) for j in range(sz2)]
    memo = {}
    def dp(i, mask):
        state = (i, mask)
        if state in memo: return memo[state]
        if i == sz1:
            ans = 0
            for j in range(sz2):
                if not (mask & (1 << j)):
                    ans += min_group2[j]
            return ans
        res = float('inf')
        for j in range(sz2):
            res = min(res, cost[i][j] + dp(i + 1, mask | (1 << j)))
        memo[state] = res
        return res
    return dp(0, 0)

